    const dominoes = [];
    for (let a = 1; a <= 6; a++) {
        for (let b = a; b <= 6; b++) {
            dominoes.push([a, b]);
        }
    }

    let max = 0;
    const edgeCount = edges.length;
    const used = new Array(dominoes.length).fill(false);
    const vertexValues = new Array(n).fill(-1);

    function backtrack(index, count) {
        if (count > max) {
            max = count;
        }
        if (index >= edgeCount) {
            return;
        }

        // Skip this edge
        backtrack(index + 1, count);

        const [u, v] = edges[index];

        // Try placing each domino on this edge
        for (let i = 0; i < dominoes.length; i++) {
            if (used[i]) continue;
            const [a, b] = dominoes[i];

            // Try direction u->v (a on u, b on v)
            if (canPlace(u, v, a, b)) {
                place(u, v, a, b, i);
                backtrack(index + 1, count + 1);
                remove(u, v, a, b, i);
            }

            // Try direction v->u (b on u, a on v)
            if (a !== b && canPlace(v, u, a, b)) {
                place(v, u, a, b, i);
                backtrack(index + 1, count + 1);
                remove(v, u, a, b, i);
            }
        }
    }

    function canPlace(u, v, a, b) {
        return (vertexValues[u] === -1 || vertexValues[u] === a) &&
               (vertexValues[v] === -1 || vertexValues[v] === b);
    }

    function place(u, v, a, b, i) {
        const prevU = vertexValues[u];
        const prevV = vertexValues[v];
        vertexValues[u] = a;
        vertexValues[v] = b;
        used[i] = true;
        // Store previous values for restoration
        place.prevU = prevU;
        place.prevV = prevV;
    }

    function remove(u, v, a, b, i) {
        vertexValues[u] = place.prevU;
        vertexValues[v] = place.prevV;
        used[i] = false;
    }

    backtrack(0, 0);
    return max;
